/**
 * O que é GERADO dentro do pacote — o que difere de um workspace de deploy do repositório.
 *
 * O `firebase.json` do repositório não serve como está por duas razões: o `predeploy` dele compila o
 * kernel (que no pacote já vem compilado, e cujo `src/` não viaja), e o hosting dele aponta para
 * `dist`. Aqui o `predeploy` compila SÓ o que o escritório escreveu.
 */

export interface RepoFunctionsPackage {
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  engines?: Record<string, string>;
}

export interface HostingConfig {
  ignore: string[];
  rewrites: unknown[];
  headers: unknown[];
}

export const packageFirebaseJson = (hosting: HostingConfig): string => JSON.stringify({
  firestore: {
    rules: 'firestore.rules',
    indexes: 'firestore.indexes.json',
  },
  storage: {
    rules: 'storage.rules',
  },
  functions: {
    source: 'functions',
    predeploy: ['npm --prefix "$RESOURCE_DIR" run build'],
  },
  hosting: {
    public: 'hosting',
    ignore: hosting.ignore,
    rewrites: hosting.rewrites,
    headers: hosting.headers,
  },
}, null, 2) + '\n';

/**
 * As dependências são copiadas INTACTAS do `functions/package.json` do repositório, para que o
 * `package-lock.json` que viaja junto continue válido. O que muda é só o entrypoint (passa a ser o
 * `index.js` que soma kernel e custom) e o `build`, que agora compila apenas `custom/`.
 */
export const packageFunctionsPackageJson = (source: RepoFunctionsPackage): string => JSON.stringify({
  name: 'microteia-functions',
  private: true,
  main: 'index.js',
  engines: source.engines ?? { node: '22' },
  scripts: {
    build: 'tsc -p custom/tsconfig.json',
  },
  dependencies: source.dependencies ?? {},
  devDependencies: source.devDependencies ?? {},
}, null, 2) + '\n';

/**
 * Entrypoint da instalação. O espalhamento mantém os nomes PLANOS (`onUserCreated`, e não
 * `kernel-onUserCreated`), que é o que os deploys por nome e os gatilhos já existentes esperam.
 */
export const packageFunctionsIndexJs = (): string => `// Generated by "microteia pack". Do not edit.
//
// The deployed function set is the compiled kernel plus whatever this installation added under
// custom/. Kernel functions cannot be overridden here: custom/ is spread last, so a name collision
// would silently replace a kernel trigger — keep your function names distinct.
const kernel = require('./lib/index.js');
const custom = require('./custom/lib/index.js');

module.exports = { ...kernel, ...custom };
`;

export const packageCustomTsconfig = (): string => JSON.stringify({
  compilerOptions: {
    module: 'commonjs',
    moduleResolution: 'node',
    target: 'es2022',
    lib: ['ES2022'],
    types: ['node'],
    rootDir: 'src',
    outDir: 'lib',
    strict: true,
    esModuleInterop: true,
    skipLibCheck: true,
    sourceMap: true,
    noImplicitReturns: true,
  },
  include: ['src'],
}, null, 2) + '\n';

export const packageCustomIndexTs = (): string => `// Cloud Functions belonging to this installation.
//
// Everything exported from this file is deployed alongside the Microteia kernel and survives a
// kernel upgrade — "microteia deploy" replaces lib/ but never touches custom/.
//
// Functions must be pinned to the same region as the rest of the installation, otherwise Firestore
// triggers will not fire. Example:
//
//   import { onCall } from 'firebase-functions/v2/https';
//
//   export const helloOffice = onCall({ region: 'southamerica-east1', cors: true }, () => {
//     return { ok: true };
//   });

export {};
`;

export const packageReadme = (version: string): string => `# Microteia ${version}

This directory is a Microteia installation package. It is deployed by the Microteia Console:

    microteia connect --project <your-firebase-project-id>
    microteia deploy --kernel <this-package>.tgz

## What is in here

| Path                     | What it is                                            |
| ------------------------ | ----------------------------------------------------- |
| \`hosting/\`               | The compiled application                              |
| \`functions/lib/\`         | The compiled Microteia Cloud Functions                |
| \`functions/custom/\`      | **Yours.** Cloud Functions this installation adds      |
| \`firestore.rules\`        | Firestore security rules                              |
| \`firestore.indexes.json\` | Firestore composite indexes                           |
| \`storage.rules\`          | Cloud Storage security rules                          |
| \`manifest.json\`          | Version, components and manual prerequisites          |

## Adding your own Cloud Functions

Write them in \`functions/custom/src/\` and export them from \`functions/custom/src/index.ts\`. They are
compiled and deployed together with the kernel, and are preserved across kernel upgrades.

\`functions/lib/\` is the kernel. It is replaced on every upgrade — do not edit it.

## Configuration

\`hosting/firebase-config.js\` is stamped by \`microteia connect\` with your Firebase project. Backend
settings, when used, go in \`functions/.env.<your-project-id>\`. Neither file should be committed to a
public repository.
`;
